import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3, smoothstep, float, texture, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, Color, DoubleSide } = THREE;

  const group = new Group();
  group.name = 'hub-journal-card-2-label';
  const cleanups = [];

  const accent = new Color('#ff2a38');
  const paper = new Color('#e8ecf2');
  const surface = new Color('#0b0b10');

  /* ---------- Card body plane (512:320 -> 2.56 x 1.6) ---------- */
  const W = 2.56;
  const H = 1.6;
  const geo = new PlaneGeometry(W, H, 1, 1);

  const mapUniform = uniform(null);
  const edgeIntensity = uniform(0.20);
  const focusGlow = uniform(0.0);

  ctx.textureLoader.loadTexture('/prism-mock/home/nodes/feature-card.png').then((tex) => {
    tex.colorSpace = THREE.SRGBColorSpace;
    mapUniform.value = tex;
  });

  const ar = uniform(accent.r), ag = uniform(accent.g), ab = uniform(accent.b);
  const accentVec = vec3(ar, ag, ab);

  const u = uv();
  const dx = u.x.min(float(1).sub(u.x));
  const dy = u.y.min(float(1).sub(u.y));
  const d = dx.min(dy);
  const edgeMask = smoothstep(float(0.035), float(0), d);
  const baseTex = texture(mapUniform, u).rgb;
  const edgeMix = edgeMask.mul(edgeIntensity.add(focusGlow));

  const mat = new MeshBasicNodeMaterial({
    transparent: true,
    side: DoubleSide,
  });
  mat.colorNode = mix(baseTex, accentVec, edgeMix);

  const plane = new Mesh(geo, mat);
  group.add(plane);

  /* ---------- Contact shadow ---------- */
  const shGeo = new PlaneGeometry(W * 1.35, H * 1.35);
  const shMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const sc = uv().sub(0.5);
  const sr = sc.length();
  shMat.colorNode = vec3(0.0, 0.0, 0.0);
  shMat.alphaNode = smoothstep(float(0.5), float(0.0), sr).mul(0.45);
  const shadow = new Mesh(shGeo, shMat);
  shadow.position.set(0, -H / 2 - 0.08, -0.02);
  shadow.rotation.x = -Math.PI / 2.2;
  group.add(shadow);

  /* ---------- Surface backing (depth) ---------- */
  const backGeo = new PlaneGeometry(W + 0.06, H + 0.06);
  const backMat = new MeshBasicNodeMaterial({ color: 0x0b0b10, transparent: true, opacity: 0.95 });
  const backing = new Mesh(backGeo, backMat);
  backing.position.z = -0.01;
  group.add(backing);

  /* ---------- Text label ---------- */
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textObjs = [];
  for (const item of items) {
    const label = ctx.fontAtlas.createText(String(item.text), {
      fontSize: item.typography?.fontSize ?? 39,
      color: paper.getHexString(),
      align: 'left',
      letterSpacingPx: 0.5,
    });
    label.position.set(-W / 2 + 0.22, -H / 2 + 0.30, 0.03);
    group.add(label);
    textObjs.push(label);
  }

  /* ---------- Accent tick mark (focus indicator) ---------- */
  const tickGeo = new PlaneGeometry(0.42, 0.03);
  const tickMat = new MeshBasicNodeMaterial({ color: accent.getHex(), transparent: true });
  const tick = new Mesh(tickGeo, tickMat);
  tick.position.set(-W / 2 + 0.45, -H / 2 + 0.62, 0.03);
  tick.scale.x = 0.0;
  group.add(tick);

  /* ---------- Cinematic primitive: parallax-scroll ---------- */
  const prim = ctx.primitives['parallax-scroll'](plane, { intensity: 0.25 });
  if (prim?.cleanup) cleanups.push(prim.cleanup);
  if (prim?.timeline) cleanups.push({ tl: prim.timeline });

  /* ---------- Interaction state ---------- */
  let hovered = false;
  let hoverTl = null;
  let pressTl = null;
  let focused = false;

  function ensureKill(store, newVal) {
    if (store.tl) store.tl.kill();
    store.tl = newVal;
  }

  group.userData.handlers = {
    hover(active) {
      const wasHovered = hovered;
      hovered = !!active;
      if (hovered === wasHovered) return;
      if (hoverTl) hoverTl.kill();
      hoverTl = gsap.timeline();
      hoverTl.to(group.position, {
        y: hovered ? '+=0.15' : '-=0.15',
        duration: 0.6,
        ease: 'power3.out',
      }, 0);
      hoverTl.to(plane.scale, {
        x: hovered ? 1.03 : 1, y: hovered ? 1.03 : 1, z: 1,
        duration: 0.6, ease: 'power3.out',
      }, 0);
      hoverTl.to(edgeIntensity, {
        value: hovered ? 0.72 : 0.20,
        duration: 0.5, ease: 'power2.out',
      }, 0);
      hoverTl.to(tick.scale, {
        x: hovered ? 1.0 : (focused ? 1.0 : 0.0),
        duration: 0.5, ease: 'power3.out',
      }, 0);
    },
    click() {
      if (pressTl) pressTl.kill();
      pressTl = gsap.timeline();
      pressTl.to(plane.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'power2.in' });
      pressTl.to(plane.scale, { x: hovered ? 1.03 : 1, y: hovered ? 1.03 : 1, duration: 0.18, ease: 'back.out(2)' });
      ctx.emit('hub-journal.select', { id: 'hub-journal-card-2', source: 'hub-journal-card-2-label' });
    },
    focus(active) {
      focused = !!active;
      if (focusGlow) {
        gsap.to(focusGlow, { value: focused ? 0.5 : 0.0, duration: 0.4, ease: 'power2.out' });
        gsap.to(tick.scale, { x: focused || hovered ? 1.0 : 0.0, duration: 0.4, ease: 'power3.out' });
      }
    },
  };

  /* ---------- Idle settle (entrance) ---------- */
  const enterTl = gsap.timeline();
  group.scale.set(1, 1, 1);
  plane.scale.set(0.96, 0.96, 1);
  group.position.z = 0.0;
  plane.position.z = -0.05;
  enterTl.to(plane.position, { z: 0, duration: 0.7, ease: 'power3.out' });
  enterTl.to(plane.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0);
  enterTl.fromTo(group.position, { x: group.position.x - 0.0 }, { x: group.position.x, duration: 0.7, ease: 'power2.out' }, 0);
  enterTl.fromTo(textObjs.map((o) => o.material), { opacity: 0 }, { opacity: 1, duration: 0.6, ease: 'power2.out' }, 0.2);
  cleanups.push(enterTl);

  /* ---------- Cleanup ---------- */
  group.userData.cleanup = () => {
    if (hoverTl) hoverTl.kill();
    if (pressTl) pressTl.kill();
    enterTl.kill();
    for (const c of cleanups) {
      if (c && typeof c.kill === 'function') c.kill();
      else if (c && c.tl && typeof c.tl.kill === 'function') c.tl.kill();
      else if (typeof c === 'function') c();
    }
    geo.dispose();
    shGeo.dispose();
    backGeo.dispose();
    tickGeo.dispose();
    mat.dispose();
    shMat.dispose();
    backMat.dispose();
    tickMat.dispose();
    if (mapUniform.value && mapUniform.value.dispose) mapUniform.value.dispose();
    if (textObjs.length) {
      for (const o of textObjs) {
        if (o.geometry && o.geometry.dispose) o.geometry.dispose();
        if (o.material && o.material.dispose) o.material.dispose();
      }
    }
  };

  return group;
}
